head.script:
scwin.screenId = "jldfil25003";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(dma_companyInfo.get("comNm")); } },
        { childId: "__rb1", attr: "label", fn: function () { return String(dma_companyInfo.get("ceoNm")); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_companyInfo.get("corpTelNo")); } },
        { childId: "__rb4", attr: "label", fn: function () { return String(dma_companyInfo.get("hpage")); } },
        { childId: "__rb5", attr: "label", fn: function () { return String(dma_companyInfo.get("majProdNm")); } },
        { childId: "__rb6", attr: "label", fn: function () { return String(dma_companyInfo.get("acntclsMm")); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb2", fn: function () { return String(dma_companyInfo.get("zipcd")) + " " + String(dma_companyInfo.get("addr")) + " " + String(dma_companyInfo.get("dtlAddr")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25003.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_GoDsclInsert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_GoDsclInsert = async function () {
    const sbmOptions = {
        id: "tx_fn_GoDsclInsert",
        method: "post",
        action: "/submission/searchDisclosureForm.do",
        ref: "dma_GoDsclInsertReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25003.tx_fn_GoDsclInsert" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_Save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Save = async function () {
    try { return await $c.data.downFile("/account/corporationReport.do", "", ($c.util.getComponent("dma_SaveReq") ? $c.util.getComponent("dma_SaveReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goDsclInsert
 * @author Inswave
 * @date 2026. 09. 29
 * @param formKorNm
 * @returns
 * @hidden N
*/
scwin.goDsclInsert = async function (formKorNm) {
    /* sdd-asis-lifecycle:begin fn_GoDsclInsert — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_GoDsclInsertReq').set('formKorNm', formKorNm);
    await scwin.tx_fn_GoDsclInsert();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_Save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = $c.util.getComponent('corpForm');
    const isCorpTelNoCk = frm.corpTelNoCk.checked;
    const isHpageCk = frm.hpageCk.checked;
    const isMajProdNmCk = frm.majProdNmCk.checked;
    if (!(isCorpTelNoCk || isHpageCk || isMajProdNmCk)) {
        await $c.win.alert('변경사항이 없습니다.');
        return;
    }
    if (isCorpTelNoCk) {
        if ($c.cm.fn_NullChk(frm.corpTelNo1) || $c.cm.fn_NullChk(frm.corpTelNo2) || $c.cm.fn_NullChk(frm.corpTelNo3)) {
            return;
        }
        if (!($c.cm.fn_IsNumber(frm.corpTelNo1) && $c.cm.fn_IsNumber(frm.corpTelNo2) && $c.cm.fn_IsNumber(frm.corpTelNo3))) {
            await $c.win.alert('대표전화번호는 숫자만 입력하세요');
            return;
        }
        const corpTelNoVal = frm.corpTelNo1.value + '-' + frm.corpTelNo2.value + '-' + frm.corpTelNo3.value;
        $c.util.getComponent('dma_GoDsclInsertReq').set('corpTelNo', corpTelNoVal);
    } else {
        $c.util.getComponent('dma_GoDsclInsertReq').set('corpTelNo', "");
    }
    if (isHpageCk) {
        if ($c.cm.fn_NullChk($c.util.getComponent('dma_SaveReq'))) {
            return;
        }
    } else {
        $c.util.getComponent('dma_SaveReq').set('hpage', "");
    }
    if (isMajProdNmCk) {
        if ($c.cm.fn_NullChk($c.util.getComponent('dma_SaveReq'))) {
            return;
        }
    } else {
        $c.util.getComponent('dma_SaveReq').set('majProdNm', "");
    }
    $c.util.getComponent('dma_GoDsclInsertReq').set('method', 'modifyCorporationReport');
    frm.action = 'corporationReport.do';
    await scwin.tx_fn_Save();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.activeInput
 * @author Inswave
 * @date 2026. 09. 29
 * @param _target
 * @returns
 * @hidden N
*/
scwin.activeInput = function (_target) {
    /* sdd-asis-lifecycle:begin fn_ActiveInput — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = $c.util.getComponent('corpForm');
    if (_target === 'corpTelNo') {
        if (frm.corpTelNoCk.checked) {
            frm.corpTelNo1.readOnly = false;
            frm.corpTelNo2.readOnly = false;
            frm.corpTelNo3.readOnly = false;
        } else {
            frm.corpTelNo1.readOnly = true;
            frm.corpTelNo2.readOnly = true;
            frm.corpTelNo3.readOnly = true;
        }
    } else {
        if (_target === 'hpage') {
            if (frm.hpageCk.checked) {
                (console.warn("[sdd] unresolved:dmap-member:" + "hpage @ dma_SaveReq.hpage"), $c.util.getComponent('dma_SaveReq')).readOnly = false;
            } else {
                (console.warn("[sdd] unresolved:dmap-member:" + "hpage @ dma_SaveReq.hpage"), $c.util.getComponent('dma_SaveReq')).readOnly = true;
            }
        } else {
            if (_target === 'majProdNm') {
                if (frm.majProdNmCk.checked) {
                    (console.warn("[sdd] unresolved:dmap-member:" + "majProdNm @ dma_SaveReq.majProdNm"), $c.util.getComponent('dma_SaveReq')).readOnly = false;
                } else {
                    (console.warn("[sdd] unresolved:dmap-member:" + "majProdNm @ dma_SaveReq.majProdNm"), $c.util.getComponent('dma_SaveReq')).readOnly = true;
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goURL = function () {
    /* sdd-asis-lifecycle:begin fn_GoURL — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    document.location.href = "/";
    /* sdd-asis-lifecycle:end */
};
